from larder.recipes.store import Cookbook
from larder.recipes.models import Recipe
def mk(n, cat='x'):
    s = Cookbook()
    for k in range(n):
        s.add(Recipe(id='k%02d' % k, title='N%02d' % k, course=cat, servings=(k * 5) % 7, cost=1.0 + k))
    return s
from larder.recipes.errors import Invalid
s = mk(2)
try:
    s.add(Recipe(id='k01', title='z', course='c'))
except Invalid as e:
    print(e, s.count(), s.get('k01').title)

